import React, { useState } from 'react';
import ReportViewer from '../components/ReportViewer';

const ReportsPage: React.FC = () => {
  const [startDate,setStartDate]=useState(new Date());
  const [endDate,setEndDate]=useState(new Date());

  return (
    <div>
      <h1>Reports</h1>
      <label>Start Date:<input type='date' onChange={e=>setStartDate(new Date(e.target.value))} /></label>
      <label>End Date:<input type='date' onChange={e=>setEndDate(new Date(e.target.value))} /></label>
      <ReportViewer tenantId='ACTIVE_TENANT_ID' startDate={startDate} endDate={endDate} />
    </div>
  );
};

export default ReportsPage;
